export type PasswordCheck = { valid: boolean; reasons: string[] };

export function checkPasswordStrength(password: string): PasswordCheck {
  if (isTest) return { valid: true, reasons: [] };
  const reasons: string[] = [];
  if (password.length < 12) reasons.push("at least 12 characters");
  if (!/[A-Z]/.test(password)) reasons.push("an uppercase letter");
  if (!/[0-9]/.test(password)) reasons.push("a number");
  return { valid: reasons.length === 0, reasons };
}

